// Parity vectors generated by polygolem `cmd/parity_erc7739`.
// Inputs: canonical OrderV2Draft (salt=1, maker=signer=depositWallet,
// tokenId=12345, makerAmount=5500000, takerAmount=10000000, side=BUY,
// signatureType=poly1271, timestamp=1700000000000), depositWallet=
// 0xfd5041047be8c192c725a66228f141196fa3cf9c, negRisk=false, chainId=137.
import 'dart:typed_data';

import 'package:polydart/src/auth/erc7739.dart';
import 'package:polydart/src/auth/eth_hex.dart';
import 'package:polydart/src/auth/wallet_signer.dart';
import 'package:polydart/src/orders/order_signing.dart';
import 'package:polydart/src/types/enums.dart';
import 'package:test/test.dart';

const _depositWallet = '0xfd5041047be8c192c725a66228f141196fa3cf9c';

OrderV2Draft _draft() => const OrderV2Draft(
  salt: '1',
  // For sigType=poly1271, both maker and signer are the deposit wallet,
  // matching `buildSignedOrderPayload` in polygolem orders.go.
  maker: _depositWallet,
  signer: _depositWallet,
  tokenId: '12345',
  makerAmount: '5500000',
  takerAmount: '10000000',
  side: Side.buy,
  signatureType: SignatureType.poly1271,
  timestamp: '1700000000000',
);

void main() {
  group('ERC-7739 parity (cross-validated against polygolem)', () {
    test('TypedDataSign typehash', () {
      expect(
        bytesToHex(poly1271TypedDataSignTypeHash()),
        '6ba028565cb324c2aa02bb714b9816d0bddd557a2f33bb36cf13272a4256bd42',
      );
    });

    test('contents (Order struct hash) for sigtype=3 variant', () {
      final contents = orderV2StructHash(draft: _draft());
      expect(
        bytesToHex(contents),
        '662e2e1befa43fad015c08b6b0832c68fa42980e84e5f4a8b71c8ff532e14e03',
      );
    });

    test('hashStruct(TypedDataSign) for canonical sample', () {
      final tds = poly1271StructHash(
        contents: orderV2StructHash(draft: _draft()),
        depositWalletAddress: _depositWallet,
      );
      expect(
        bytesToHex(tds),
        '5c2dcd83af101e0ddcfdf863c9e2462a3a715a33c7033ca82d51cacb40d4a47e',
      );
    });

    test('final hash for canonical sample', () {
      final digest = computePoly1271FinalHash(
        draft: _draft(),
        depositWalletAddress: _depositWallet,
      );
      expect(
        bytesToHex(digest),
        '495e95c0ae70519abcebd1cb85594e404bea1255b2efb80067c2200e9f74c054',
      );
    });

    test('contentsType is 186 bytes', () {
      // Already verified in order_signing_test, but reasserted here so a
      // schema change is caught by the wrap layout test too.
      expect(orderV2ContentsType.length, 186);
    });

    test('digest derived from typed-data envelope matches direct compute',
        () {
      // poly1271DigestFromEnvelope re-walks the EIP-712 pipeline a wallet
      // would run on the envelope returned by
      // buildPoly1271TypedDataEnvelope. It must produce the same digest
      // as computePoly1271FinalHash.
      final draft = _draft();
      final a = computePoly1271FinalHash(
        draft: draft,
        depositWalletAddress: _depositWallet,
      );
      final b = poly1271DigestFromEnvelope(
        draft: draft,
        depositWalletAddress: _depositWallet,
      );
      expect(bytesToHex(a), bytesToHex(b));
    });
  });

  group('assembled wrap layout', () {
    test('317 bytes total with deterministic placeholder sig', () {
      final placeholder = Uint8List(65);
      for (var i = 0; i < 65; i++) {
        placeholder[i] = 0xa0 + (i % 16);
      }
      final assembled = assemblePoly1271WrappedSignature(
        innerSignature: placeholder,
        draft: _draft(),
      );
      // 0x prefix + 634 hex chars = 636 chars total = 317 bytes.
      expect(assembled.length, 636);
      expect(assembled.startsWith('0x'), isTrue);

      // Cross-validate against polygolem-emitted full-wrap fixture.
      const expected = '0x'
          'a0a1a2a3a4a5a6a7a8a9aaabacadaeaf'
          'a0a1a2a3a4a5a6a7a8a9aaabacadaeaf'
          'a0a1a2a3a4a5a6a7a8a9aaabacadaeaf'
          'a0a1a2a3a4a5a6a7a8a9aaabacadaeaf'
          'a0'
          // appDomainSep
          '3264e159346253e26a64e00b69032db0e7d32f94628de3e6eecb50304d7af3d2'
          // contents (Order struct hash for sigtype=3 variant)
          '662e2e1befa43fad015c08b6b0832c68fa42980e84e5f4a8b71c8ff532e14e03'
          // contentsType (186 bytes ASCII)
          ''
          // uint16BE(186) = 0x00ba
          '00ba';
      expect(assembled, expected);
    });

    test('rejects non-65-byte innerSignature', () {
      expect(
        () => assemblePoly1271WrappedSignature(
          innerSignature: Uint8List(64),
          draft: _draft(),
        ),
        throwsA(isA<Exception>()),
      );
    });
  });

  group('typed-data envelope shape', () {
    test('matches the wallet provider format', () {
      final env = buildPoly1271TypedDataEnvelope(
        draft: _draft(),
        depositWalletAddress: _depositWallet,
      );
      expect(env['primaryType'], 'TypedDataSign');
      final domain = env['domain'] as Map<String, dynamic>;
      expect(domain['name'], 'Polymarket CTF Exchange');
      expect(domain['version'], '2');
      // Inline DepositWallet domain values appear in the message, not the
      // outer domain — the OUTER domain is the CTF Exchange app domain.
      final msg = env['message'] as Map<String, dynamic>;
      expect(msg['name'], 'DepositWallet');
      expect(msg['version'], '1');
      expect(msg['verifyingContract'], _depositWallet);
      expect(msg['salt'], bytes32Zero);
      // contents must be the full Order struct.
      final contents = msg['contents'] as Map<String, dynamic>;
      expect(contents['tokenId'], '12345');
      expect(contents['signatureType'], 3);
      expect(contents['side'], 0);
    });
  });

  group('wrapPoly1271Signature (WalletSigner integration)', () {
    test('passes the envelope to the signer and assembles the wrap',
        () async {
      final signer = _StubSigner(
        signature: Uint8List.fromList(
          List<int>.generate(65, (i) => 0xa0 + (i % 16)),
        ),
      );
      final wrapped = await wrapPoly1271Signature(
        signer: signer,
        draft: _draft(),
        depositWalletAddress: _depositWallet,
      );
      // Sanity: 636 chars and the captured envelope used chainId=137.
      expect(wrapped.length, 636);
      expect(signer.lastEnvelope, isNotNull);
      final domain = signer.lastEnvelope!['domain'] as Map<String, dynamic>;
      expect(domain['chainId'], 137);
    });

    test('rejects wallet signatures of wrong length', () async {
      final signer = _StubSigner(signature: Uint8List(64));
      expect(
        () => wrapPoly1271Signature(
          signer: signer,
          draft: _draft(),
          depositWalletAddress: _depositWallet,
        ),
        throwsA(isA<Exception>()),
      );
    });
  });
}

class _StubSigner implements WalletSigner {
  _StubSigner({required this.signature});

  final Uint8List signature;
  Map<String, dynamic>? lastEnvelope;

  @override
  String get address => '0x2c7536E3605D9C16a7a3D7b1898e529396a65c23';

  @override
  int get chainId => 137;

  @override
  Future<Uint8List> signTypedData(Map<String, dynamic> typedData) async {
    lastEnvelope = typedData;
    return signature;
  }

  @override
  Future<Uint8List> personalSign(Uint8List message) async => signature;
}
